// Intended function: validate paired portal power/stability/network membership before emitting a transit plan for the movement/authority owner to commit.
#include "world/PortalNetwork.hpp"
#include <algorithm>
namespace elysium{void PortalNetwork::upsert(PortalEndpoint p){portals_[p.portalId]=p;}PortalTransitPlan PortalNetwork::plan(const PortalTransitRequest&r,float power)const{PortalTransitPlan o;o.requestId=r.requestId;o.actorId=r.actorId;auto a=portals_.find(r.fromPortal),b=portals_.find(r.toPortal);if(a==portals_.end()||b==portals_.end()){o.failureCode=1;return o;}if(!a->second.enabled||!b->second.enabled||a->second.networkId!=b->second.networkId){o.failureCode=2;return o;}if(a->second.stability<.25f||b->second.stability<.25f){o.failureCode=3;return o;}o.energyCost=(a->second.powerRequired+b->second.powerRequired)*(1+std::max(0.f,r.mass)*.01f);if(power<o.energyCost){o.failureCode=4;return o;}o.allowed=true;o.fromAddress=a->second.address;o.toAddress=b->second.address;return o;}std::vector<PortalEndpoint>PortalNetwork::network(std::uint64_t n)const{std::vector<PortalEndpoint>o;for(auto&[_,p]:portals_)if(p.networkId==n)o.push_back(p);std::sort(o.begin(),o.end(),[](auto&a,auto&b){return a.portalId<b.portalId;});return o;}}
